function resolvePath() {
  try {
    document.querySelector('#result').textContent = new URL(
      document.querySelector('#path').value,
      document.querySelector('#base').value,
    ).href;
  } catch {
    document.querySelector('#result').textContent = '请输入有效的 URL';
  }
}
document.querySelector('#resolve').onclick = resolvePath;
resolvePath();

