.far {
  transform: translateZ(-80px) rotate3d(1, 1, 0, 25deg);
}

.track {
  padding: 16px;
  height: 160px;
  background: #edf5ef;
}
.runner {
  width: 100px;
  padding: 12px;
  background: #8ac09c;
  animation: travel 2s ease-in-out 0.5s infinite alternate both;
}
.runner:hover {
  animation-play-state: paused;
}
@keyframes travel {
  from {
    transform: translateX(0);
    opacity: 0.6;
  }
  to {
    transform: translateX(120px);
    opacity: 1;
  }
}
@media (prefers-reduced-motion: reduce) {
  .runner {
    animation: none;
  }
}

.sprite-frame {
  width: 80px;
  height: 80px;
  background-image: linear-gradient(
    to right,
    #69a982 0 25%,
    #dbb265 25% 50%,
    #7b9fce 50% 75%,
    #b48bc4 75%
  );
  background-size: 320px 80px;
  animation: frames 1.2s steps(4) infinite;
}
@keyframes frames {
  to {
    background-position: -320px 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .sprite-frame {
    animation: none;
  }
}

.moving {
  width: 70px;
  margin: 35px;
  animation: slide 3s ease-in-out infinite alternate;
}
.spinning {
  padding: 15px;
  text-align: center;
  background: #c6e2cf;
  animation: spin 2s linear infinite;
}
@keyframes slide {
  to {
    transform: translateX(140px);
  }
}
@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}
@media (prefers-reduced-motion: reduce) {
  .moving,
  .spinning {
    animation: none;
  }
}

.marquee {
  overflow: hidden;
  background: #deede2;
}
.marquee-track {
  display: flex;
  width: max-content;
  animation: marquee 12s linear infinite;
}
.marquee-track > div {
  flex-shrink: 0;
  padding: 20px;
  white-space: nowrap;
}
.marquee:hover .marquee-track,
.marquee:focus-within .marquee-track {
  animation-play-state: paused;
}
@keyframes marquee {
  to {
    transform: translateX(-50%);
  }
}
@media (prefers-reduced-motion: reduce) {
  .marquee-track {
    animation: none;
  }
}

.motion-ball {
  width: 60px;
  height: 60px;
  border-radius: 50%;
  background: #78a486;
  animation: travel 2s ease-in-out infinite alternate;
}
@keyframes travel {
  to {
    transform: translateX(180px);
  }
}
@media (prefers-reduced-motion: reduce) {
  .motion-ball {
    animation: none;
  }
}

