document.getElementById('syncBtn').addEventListener('click', () => {
  const text = document.getElementById('draft').value;
  const dest = document.getElementById('result');
  dest.textContent = '';
  text
    .split(/\n+/)
    .filter(Boolean)
    .forEach((line) => {
      const el = document.createElement(line.startsWith('# ') ? 'h2' : 'p');
      el.textContent = line.replace(/^# /, '').replace(/^- /, '• ');
      dest.append(el);
    });
});

