function bubbleSort(values) {
  const result = [...values];
  for (let end = result.length - 1; end > 0; end -= 1) {
    let changed = false;
    for (let i = 0; i < end; i += 1) {
      if (result[i] > result[i + 1]) {
        [result[i], result[i + 1]] = [result[i + 1], result[i]];
        changed = true;
      }
    }
    if (!changed) break;
  }
  return result;
}
