let x = 2,
  y = 2;
const area = document.getElementById('moveArea');
function render() {
  document.getElementById('dot').style.left = x * 20 + '%';
  document.getElementById('dot').style.top = y * 20 + '%';
  document.getElementById('coords').textContent = '位置：(' + x + ', ' + y + ')';
}
area.addEventListener('keydown', (e) => {
  const map = {
    ArrowLeft: [-1, 0],
    ArrowRight: [1, 0],
    ArrowUp: [0, -1],
    ArrowDown: [0, 1],
  };
  if (map[e.key]) {
    e.preventDefault();
    x = Math.max(0, Math.min(4, x + map[e.key][0]));
    y = Math.max(0, Math.min(4, y + map[e.key][1]));
    render();
  } else if (e.key.toLowerCase() === 'r') {
    x = 2;
    y = 2;
    render();
  }
});

