let over = 0;
let enter = 0;
const zone = document.querySelector('#zone');
function render() {
  document.querySelector('#counts').textContent =
    'mouseover：' + over + '\nmouseenter：' + enter;
}
zone.addEventListener('mouseover', () => {
  over += 1;
  render();
});
zone.addEventListener('mouseenter', () => {
  enter += 1;
  render();
});
render();

const items = document.getElementById('items');
document.getElementById('addItem').addEventListener('click', () => {
  const item = document.createElement('li');
  item.textContent = '新课程 ';
  const button = document.createElement('button');
  button.dataset.action = 'remove';
  button.textContent = '删除';
  item.append(button);
  items.append(item);
});
items.addEventListener('click', (event) => {
  const button = event.target.closest('[data-action="remove"]');
  if (button && items.contains(button)) button.closest('li').remove();
});

document.addEventListener('course:complete', (event) => {
  document.getElementById('eventResult').textContent = event.detail.title + ' 已完成';
});
document.getElementById('complete').addEventListener('click', (event) => {
  event.target.dispatchEvent(
    new CustomEvent('course:complete', {
      detail: { title: '事件系统' },
      bubbles: true,
    }),
  );
});

let controller;
let count = 0;
const output = document.getElementById('listenStatus');
document.getElementById('listen').addEventListener('click', () => {
  controller?.abort();
  controller = new AbortController();
  document.getElementById('fire').addEventListener(
    'click',
    () => {
      output.textContent = '监听收到 ' + ++count + ' 次点击';
    },
    { signal: controller.signal },
  );
  output.textContent = '监听已启动';
});
document.getElementById('stop').addEventListener('click', () => {
  controller?.abort();
  output.textContent = '监听已停止';
});

document.getElementById('preferences').addEventListener('submit', (event) => {
  event.preventDefault();
  const form = new FormData(event.target);
  const result = { nickname: form.get('nickname'), skills: form.getAll('skill') };
  document.getElementById('data').textContent = JSON.stringify(result, null, 2);
});

const input = document.querySelector('#password');
const toggle = document.querySelector('#toggle');
toggle.onclick = () => {
  const visible = input.type === 'password';
  input.type = visible ? 'text' : 'password';
  toggle.setAttribute('aria-pressed', String(visible));
  toggle.textContent = visible ? '隐藏密码' : '显示密码';
};

const all = document.querySelector('#all');
const items = [...document.querySelectorAll('#items input')];
function sync() {
  const selected = items.filter((item) => item.checked);
  all.checked = selected.length === items.length;
  all.indeterminate = selected.length > 0 && selected.length < items.length;
  document.querySelector('#summary').textContent = '已选' + selected.length + '项';
}
all.onchange = () => {
  items.forEach((item) => (item.checked = all.checked));
  sync();
};
items.forEach((item) => (item.onchange = sync));
sync();

let saved = false;
const button = document.querySelector('#favorite');
button.onclick = () => {
  saved = !saved;
  button.setAttribute('aria-pressed', String(saved));
  button.textContent = saved ? '★ 已收藏' : '☆ 收藏';
  document.querySelector('#feedback').textContent = saved
    ? '已加入当前预览的收藏'
    : '已取消收藏';
};

