const articles = [
  'HTML 标签一览',
  'CSS 网格布局',
  'JavaScript 事件监听',
  'HTML 表单基础',
  'CSS 动画效果',
  'JavaScript 数组与对象',
];
const q = document.getElementById('query'),
  list = document.getElementById('results'),
  count = document.getElementById('resultCount');
function render() {
  const items = articles.filter((s) =>
    s.toLowerCase().includes(q.value.trim().toLowerCase()),
  );
  count.textContent = '找到 ' + items.length + ' 条结果';
  list.replaceChildren();
  if (!items.length) {
    const p = document.createElement('p');
    p.className = 'no-results';
    p.textContent = '没有匹配的文章，换个关键词试试';
    list.append(p);
  }
  items.forEach((text, i) => {
    const el = document.createElement('div');
    el.className = 'result-item';
    const b = document.createElement('b');
    b.textContent = text;
    const s = document.createElement('span');
    s.textContent = '示例文章 · 阅读 ' + (i + 3) + ' 分钟';
    el.append(b, s);
    list.append(el);
  });
}
q.addEventListener('input', render);
render();

const products = [
  { name: '笔记本', price: 12 },
  { name: '桌面灯', price: 48 },
  { name: '背包', price: 89 },
];
function render() {
  const min = Number(document.querySelector('#min').value);
  const max = Number(document.querySelector('#max').value);
  const status = document.querySelector('#status');
  const list = document.querySelector('#goods');
  list.replaceChildren();
  if (!Number.isFinite(min) || !Number.isFinite(max) || min < 0 || min > max) {
    status.textContent = '请输入有效范围：最低价不能超过最高价';
    return;
  }
  const selected = products.filter((item) => item.price >= min && item.price <= max);
  for (const item of selected) {
    const li = document.createElement('li');
    li.textContent = item.name + ' · ￥' + item.price.toFixed(2);
    list.append(li);
  }
  status.textContent = selected.length
    ? selected.length + '件商品'
    : '这个范围没有商品';
}
