const products = [
  { name: '便携水杯', price: 79, sale: true, icon: '☕' },
  { name: '无线耳机', price: 239, sale: false, icon: '♫' },
  { name: '阅读台灯', price: 159, sale: true, icon: '✦' },
  { name: '旅行背包', price: 299, sale: false, icon: '▣' },
  { name: '桌面支架', price: 49, sale: true, icon: '△' },
  { name: '蓝牙键盘', price: 189, sale: false, icon: '⌨' },
];
const list = document.getElementById('productList');
function draw() {
  let items = products.filter(
    (p) => !document.getElementById('saleOnly').checked || p.sale,
  );
  const order = document.getElementById('sorting').value;
  if (order === 'asc') items.sort((a, b) => a.price - b.price);
  if (order === 'desc') items.sort((a, b) => b.price - a.price);
  list.replaceChildren();
  items.forEach((p) => {
    const card = document.createElement('div');
    card.className = 'product';
    const img = document.createElement('div');
    img.textContent = p.icon;
    const b = document.createElement('b');
    b.textContent = p.name + (p.sale ? ' · 优惠' : '');
    const s = document.createElement('small');
    s.textContent = '¥' + p.price;
    card.append(img, b, s);
    list.append(card);
  });
}
document.getElementById('sorting').addEventListener('change', draw);
document.getElementById('saleOnly').addEventListener('change', draw);
draw();

