const form = document.querySelector('#registration');
function validate() {
  const username = document.querySelector('#username');
  const first = document.querySelector('#first-password');
  const confirmation = document.querySelector('#confirmation');
  const nameValid = /^[a-zA-Z0-9_]{6,16}$/.test(username.value);
  const passwordValid = first.value.length >= 6 && first.value === confirmation.value;
  username.setAttribute('aria-invalid', String(!nameValid));
  confirmation.setAttribute('aria-invalid', String(!passwordValid));
  document.querySelector('#name-error').textContent = nameValid
    ? ''
    : '用户名格式不符合要求';
  document.querySelector('#password-error').textContent = passwordValid
    ? ''
    : '示例密码需至少6位，且两次相同';
  return nameValid && passwordValid && document.querySelector('#terms').checked;
}
form.addEventListener('submit', (event) => {
  event.preventDefault();
  const valid = validate();
  document.querySelector('#status').textContent = valid
    ? '验证通过（未注册真实账户）'
    : '请检查字段并确认协议';
  if (!valid) form.querySelector('[aria-invalid=true]')?.focus();
});
form.addEventListener('change', validate);

let balance = 10000;
function change(direction) {
  const value = document.querySelector('#amount').value;
  const cents = Math.round(Number(value) * 100);
  const message = document.querySelector('#message');
  if (!value.trim() || !Number.isSafeInteger(cents) || cents <= 0) {
    message.textContent = '请输入有效的正金额';
    return;
  }
  if (direction === -1 && cents > balance) {
    message.textContent = '余额不足';
    return;
  }
  balance += direction * cents;
  document.querySelector('#balance').textContent = (balance / 100).toFixed(2);
  message.textContent = direction === 1 ? '存入成功' : '取出成功';
}
document.querySelector('#deposit').onclick = () => change(1);
document.querySelector('#withdraw').onclick = () => change(-1);

let target;
let remaining;
const check = document.querySelector('#check');
const result = document.querySelector('#result');
function restart() {
  target = Math.floor(Math.random() * 20) + 1;
  remaining = 5;
  check.disabled = false;
  result.textContent = '还有5次机会';
}
check.onclick = () => {
  const raw = document.querySelector('#guess').value;
  const value = Number(raw);
  if (!raw || !Number.isInteger(value) || value < 1 || value > 20) {
    result.textContent = '请输入1到20的整数';
    return;
  }
  remaining -= 1;
  if (value === target) {
    result.textContent = '猜对了！';
    check.disabled = true;
  } else if (remaining === 0) {
    result.textContent = '机会用完，答案是' + target;
    check.disabled = true;
  } else
    result.textContent =
      (value < target ? '偏小' : '偏大') + '，剩余' + remaining + '次';
};
document.querySelector('#restart').onclick = restart;
restart();

