const slides = ['HTML · 结构', 'CSS · 布局', 'JavaScript · 交互'];
let index = 0;
let paused = false;
let timer;
let startX = null;
const carousel = document.querySelector('#carousel');
const dots = document.querySelector('#dots');
slides.forEach((_, i) => {
  const button = document.createElement('button');
  button.textContent = String(i + 1);
  button.setAttribute('aria-label', '转到第' + (i + 1) + '项');
  button.onclick = () => move(i);
  dots.append(button);
});
function move(next) {
  index = (next + slides.length) % slides.length;
  document.querySelector('#slide').textContent = slides[index];
  [...dots.children].forEach((button, i) =>
    button.setAttribute('aria-pressed', String(i === index)),
  );
}
function stop() {
  clearInterval(timer);
}
function start() {
  stop();
  if (!paused && !matchMedia('(prefers-reduced-motion: reduce)').matches)
    timer = setInterval(() => move(index + 1), 3000);
}
document.querySelector('#previous').onclick = () => move(index - 1);
document.querySelector('#next').onclick = () => move(index + 1);
document.querySelector('#pause').onclick = (event) => {
  paused = !paused;
  event.currentTarget.setAttribute('aria-pressed', String(paused));
  event.currentTarget.textContent = paused ? '继续自动播放' : '暂停自动播放';
  paused ? stop() : start();
};
carousel.addEventListener('pointerenter', stop);
carousel.addEventListener('pointerleave', () => {
  if (!carousel.contains(document.activeElement)) start();
});
carousel.addEventListener('focusin', stop);
carousel.addEventListener('focusout', (event) => {
  if (!carousel.contains(event.relatedTarget)) start();
});
carousel.addEventListener('pointerdown', (event) => (startX = event.clientX));
carousel.addEventListener('pointerup', (event) => {
  if (startX !== null && Math.abs(event.clientX - startX) > 40)
    move(index + (event.clientX < startX ? 1 : -1));
  startX = null;
});
carousel.addEventListener('pointercancel', () => (startX = null));
move(0);
start();

