const medium = document.querySelector('#medium');
const mask = document.querySelector('#mask');
const zoom = document.querySelector('#zoom');
let x = 70;
let y = 70;
function render() {
  const maxX = medium.clientWidth - mask.offsetWidth;
  const maxY = medium.clientHeight - mask.offsetHeight;
  x = Math.max(0, Math.min(maxX, x));
  y = Math.max(0, Math.min(maxY, y));
  mask.style.left = x + 'px';
  mask.style.top = y + 'px';
  const ratio = zoom.clientWidth / mask.offsetWidth;
  zoom.style.backgroundSize =
    medium.clientWidth * ratio + 'px ' + medium.clientHeight * ratio + 'px';
  zoom.style.backgroundPosition = -x * ratio + 'px ' + -y * ratio + 'px';
  document.querySelector('#coords').textContent =
    '遮罩：' + Math.round(x) + '，' + Math.round(y);
}
medium.addEventListener('pointermove', (event) => {
  const rect = medium.getBoundingClientRect();
  x = event.clientX - rect.left - mask.offsetWidth / 2;
  y = event.clientY - rect.top - mask.offsetHeight / 2;
  render();
});
medium.addEventListener('keydown', (event) => {
  const map = {
    ArrowLeft: [-10, 0],
    ArrowRight: [10, 0],
    ArrowUp: [0, -10],
    ArrowDown: [0, 10],
  };
  if (!map[event.key]) return;
  event.preventDefault();
  x += map[event.key][0];
  y += map[event.key][1];
  render();
});
render();

