let values = ['确定需求', '设计页面', '编写代码', '测试交互', '发布上线'];
let dragging = null;
const list = document.getElementById('dragList');
function move(from, to) {
  if (to < 0 || to >= values.length) return;
  const item = values.splice(from, 1)[0];
  values.splice(to, 0, item);
  render();
}
function render() {
  list.replaceChildren();
  values.forEach((name, i) => {
    const li = document.createElement('li');
    li.draggable = true;
    li.dataset.index = i;
    const handle = document.createElement('span');
    handle.textContent = '⠿';
    handle.className = 'handle';
    const title = document.createElement('span');
    title.className = 'task-name';
    title.textContent = name;
    const up = document.createElement('button');
    up.textContent = '↑';
    up.setAttribute('aria-label', '上移 ' + name);
    up.onclick = () => move(i, i - 1);
    const down = document.createElement('button');
    down.textContent = '↓';
    down.setAttribute('aria-label', '下移 ' + name);
    down.onclick = () => move(i, i + 1);
    li.append(handle, title, up, down);
    li.addEventListener('dragstart', () => {
      dragging = i;
      li.classList.add('dragging');
    });
    li.addEventListener('dragover', (e) => e.preventDefault());
    li.addEventListener('drop', (e) => {
      e.preventDefault();
      if (dragging !== null) move(dragging, i);
      dragging = null;
    });
    li.addEventListener('dragend', () => {
      dragging = null;
      li.classList.remove('dragging');
    });
    list.append(li);
  });
}
render();

