js:
function throttle(callback, delay) {
  let previous = -Infinity;
  return function (...args) {
    const now = performance.now();
    if (now - previous >= delay) {
      previous = now;
      callback.apply(this, args);
    }
  };
}
let raw = 0;
let limited = 0;
const update = throttle(
  () => (document.querySelector('#limited').textContent = '节流' + ++limited + '次'),
  300,
);
function handle() {
  document.querySelector('#raw').textContent = '原始' + ++raw + '次';
  update();
}
document.querySelector('#pad').addEventListener('pointermove', handle);
document.querySelector('#pad').addEventListener('keydown', handle);

