function open() {
  clearTimeout(timer);
  panel.hidden = false;
  trigger.setAttribute('aria-expanded', 'true');
}
function close() {
  panel.hidden = true;
  trigger.setAttribute('aria-expanded', 'false');
}
wrap.addEventListener('pointerenter', open);
