js:
const questions = [
  {
    title: '哪个元素用于导航区域？',
    options: ['nav', 'div', 'span'],
    answer: 0,
    explain: 'nav 为主要导航提供语义。',
  },
  {
    title: '哪个属性设置网格列？',
    options: ['display', 'grid-template-columns', 'color'],
    answer: 1,
    explain: 'grid-template-columns 定义列轨道。',
  },
  {
    title: '哪个方法绑定事件？',
    options: ['JSON.parse', 'addEventListener', 'slice'],
    answer: 1,
    explain: 'addEventListener 为目标注册监听器。',
  },
];
let index = 0;
let score = 0;
let answered = false;
function render() {
  answered = false;
  const question = questions[index];
  const area = document.getElementById('questionArea');
  area.replaceChildren();
  const legend = document.createElement('legend');
  legend.textContent = question.title;
  area.append(legend);
  question.options.forEach((option, i) => {
    const label = document.createElement('label');
    const input = document.createElement('input');
    input.type = 'radio';
    input.name = 'answer';
    input.value = i;
    input.required = true;
    label.append(input, document.createTextNode(' ' + option));
    area.append(label);
  });
  document.getElementById('questionProgress').textContent =
    '第 ' + (index + 1) + ' / ' + questions.length + ' 题';
  document.getElementById('quizExplanation').textContent = '';
  document.getElementById('quizNext').textContent = '提交答案';
}
document.getElementById('quizForm').addEventListener('submit', (event) => {
  event.preventDefault();
  if (!answered) {
    const chosen = Number(new FormData(event.target).get('answer'));
    if (chosen === questions[index].answer) score++;
    document.getElementById('quizExplanation').textContent =
      (chosen === questions[index].answer ? '正确！' : '再记一下：') +
      questions[index].explain;
    document
      .querySelectorAll('[name=answer]')
      .forEach((input) => (input.disabled = true));
    document.getElementById('quizNext').textContent = '下一题 / 查看结果';
    answered = true;
    return;
  }
  if (++index < questions.length) render();
  else {
    document.getElementById('quizForm').hidden = true;
    document.getElementById('questionProgress').textContent =
      '完成！得分 ' + score + ' / ' + questions.length;
    document.getElementById('quizRestart').hidden = false;
  }
});
document.getElementById('quizRestart').addEventListener('click', () => {
  index = 0;
  score = 0;
  document.getElementById('quizForm').hidden = false;
  document.getElementById('quizRestart').hidden = true;
  render();
});
render();

let nextId = 1;
let records = [];
function render() {
  const body = document.getElementById('records');
  body.replaceChildren();
  for (const record of records) {
    const row = document.createElement('tr');
    const title = document.createElement('td');
    title.textContent = record.title;
    const amount = document.createElement('td');
    amount.textContent = (record.cents / 100).toFixed(2);
    const action = document.createElement('td');
    const button = document.createElement('button');
    button.textContent = '删除';
    button.setAttribute('aria-label', '删除' + record.title);
    button.addEventListener('click', () => {
      records = records.filter((item) => item.id !== record.id);
      render();
    });
    action.append(button);
    row.append(title, amount, action);
    body.append(row);
  }
  document.getElementById('expenseTotal').textContent = records.length
    ? '合计 ¥' + (records.reduce((sum, item) => sum + item.cents, 0) / 100).toFixed(2)
    : '暂无记录，先加入一笔支出。';
}
document.getElementById('expenseForm').addEventListener('submit', (event) => {
  event.preventDefault();
  const data = new FormData(event.target);
  const title = data.get('title').trim();
  if (!title) return;
  const [whole, fraction = ''] = data.get('amount').split('.');
  const cents = Number(whole) * 100 + Number(fraction.padEnd(2, '0').slice(0, 2));
  if (!Number.isSafeInteger(cents) || cents <= 0) return;
  records.push({ id: nextId++, title, cents });
  event.target.reset();
  render();
});
render();

