js:
let remaining = 60000;
let deadline = 0;
let timer;
let running = false;
const clock = document.getElementById('clock');
const button = document.getElementById('focusStart');
function display() {
  const seconds = Math.ceil(Math.max(0, remaining) / 1000);
  clock.textContent =
    String(Math.floor(seconds / 60)).padStart(2, '0') +
    ':' +
    String(seconds % 60).padStart(2, '0');
}
function stop() {
  clearInterval(timer);
  running = false;
  button.textContent = '继续';
}
function reset() {
  stop();
  remaining =
    Math.max(
      5,
      Math.min(3600, Number(document.getElementById('duration').value) || 60),
    ) * 1000;
  button.textContent = '开始';
  document.getElementById('focusState').textContent = '准备好了';
  display();
}
button.addEventListener('click', () => {
  if (running) {
    remaining = Math.max(0, deadline - Date.now());
    stop();
    display();
    document.getElementById('focusState').textContent = '已暂停';
    return;
  }
  if (remaining <= 0) reset();
  deadline = Date.now() + remaining;
  running = true;
  button.textContent = '暂停';
  document.getElementById('focusState').textContent = '专注进行中';
  timer = setInterval(() => {
    remaining = Math.max(0, deadline - Date.now());
    display();
    if (remaining === 0) {
      stop();
      button.textContent = '再来一次';
      document.getElementById('focusState').textContent = '完成，休息一下。';
    }
  }, 100);
});
document.getElementById('focusReset').addEventListener('click', reset);
document.getElementById('duration').addEventListener('change', reset);
reset();

